import Foundation
struct TodoItem: Identifiable, Codable, Equatable {
    let id: UUID
    var title: String
    var done: Bool
    init(title: String) {
        id = UUID()
        self.title = title
        done = false
    }
}

struct TodoStore {
    private(set) var items: [TodoItem] = []
    mutating func add(_ title: String) {
        let t = title.trimmingCharacters(in: .whitespaces)
        guard !t.isEmpty else { return }
        items.append(TodoItem(title: t))
    }
    mutating func toggle(_ id: UUID) {
        guard let i = items.firstIndex(where: { $0.id == id }) else { return }
        items[i].done.toggle()
    }
    var remaining: Int { items.filter { !$0.done }.count }
}

extension TodoStore {
    func encoded() throws -> Data { try JSONEncoder().encode(items) }
    mutating func load(_ data: Data) throws {
        items = try JSONDecoder().decode([TodoItem].self, from: data)
    }
}

var store = TodoStore()
store.add("Learn Swift")
store.add("  ")
if let first = store.items.first { store.toggle(first.id) }
print(store.items.count, store.remaining) // 1 0

