func fetchPost() async throws -> Post {
    let url = URL(string: "https://jsonplaceholder.typicode.com/posts/1")!
    let (data, response) = try await URLSession.shared.data(from: url)
    guard let http = response as? HTTPURLResponse, http.statusCode == 200 else {
        throw URLError(.badServerResponse)
    }
    return try JSONDecoder().decode(Post.self, from: data)
}

func send(_ post: Post) async throws {
    var req = URLRequest(url: URL(string: "https://example.com/api/posts")!)
    req.httpMethod = "POST"
    req.setValue("application/json", forHTTPHeaderField: "Content-Type")
    req.httpBody = try JSONEncoder().encode(post)
    _ = try await URLSession.shared.data(for: req)
}

func load() async {
    do {
        let p = try await fetchPost()
        print(p.title)
    } catch let e as URLError where e.code == .notConnectedToInternet {
        print("Offline")
    } catch {
        print("Failed: \(error)")
    }
}

